CREATE TABLE `chapters` (`id` TEXT NOT NULL, `editionId` TEXT NOT NULL, `title` TEXT, `startPositionMs` INTEGER NOT NULL, `orderIndex` INTEGER NOT NULL, `createdFrom` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`editionId`) REFERENCES `editions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `bookmarks` (`id` TEXT NOT NULL, `editionId` TEXT NOT NULL, `positionMs` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `type` TEXT NOT NULL, `noteText` TEXT, `remoteId` TEXT, `syncStatus` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`editionId`) REFERENCES `editions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `listening_progress` (`id` TEXT NOT NULL, `editionId` TEXT NOT NULL, `currentPositionMs` INTEGER NOT NULL, `lastPlayedAt` INTEGER NOT NULL, `status` TEXT NOT NULL, `playbackSpeed` REAL NOT NULL, `remoteId` TEXT, `syncStatus` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`editionId`) REFERENCES `editions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `collections` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `icon` TEXT, `remoteId` TEXT, `syncStatus` TEXT NOT NULL, PRIMARY KEY(`id`));
