CREATE TABLE `collection_book_cross_ref` (`collectionId` TEXT NOT NULL, `bookId` TEXT NOT NULL, PRIMARY KEY(`collectionId`, `bookId`), FOREIGN KEY(`collectionId`) REFERENCES `collections`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`bookId`) REFERENCES `books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `favorite_books` (`bookId` TEXT NOT NULL, `addedAt` INTEGER NOT NULL, PRIMARY KEY(`bookId`), FOREIGN KEY(`bookId`) REFERENCES `books`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `listening_sessions` (`id` TEXT NOT NULL, `editionId` TEXT NOT NULL, `startedAt` INTEGER NOT NULL, `endedAt` INTEGER, `durationListenedMs` INTEGER NOT NULL, `endReason` TEXT, `sessionState` TEXT NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`editionId`) REFERENCES `editions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `edition_match_decisions` (`id` TEXT NOT NULL, `subjectEditionId` TEXT NOT NULL, `comparedAgainstEditionId` TEXT, `signalsSnapshot` TEXT NOT NULL, `userDecision` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`subjectEditionId`) REFERENCES `editions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`comparedAgainstEditionId`) REFERENCES `editions`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE TABLE `chapter_completions` (`chapterId` TEXT NOT NULL, `editionId` TEXT NOT NULL, `completedAtMs` INTEGER NOT NULL, PRIMARY KEY(`chapterId`), FOREIGN KEY(`chapterId`) REFERENCES `chapters`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`editionId`) REFERENCES `editions`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
